const filas = $input.all().map(item => item.json).filter(r => /^\d{4}-\d{2}-\d{2}$/.test(String(r.fecha ?? '')));
if (!filas.length) return [];
const hoy = String(filas[0].fecha_hoy ?? '');
const actuales = filas.filter(r => String(r.fecha) === hoy);
if (!actuales.length) return [];
const estado = $getWorkflowStaticData('global');
if (estado.ultimaFechaAvisada === hoy) return [];
const historial = filas.map(r => ({
  fecha: String(r.fecha),
  comprado: Number(r.pan_comprado),
  stock: Number(r.stock_pan)
})).filter(r => Number.isFinite(r.comprado) && r.comprado >= 0 && Number.isFinite(r.stock) && r.stock >= 0).sort((a, b) => a.fecha.localeCompare(b.fecha));
const actual = historial.find(r => r.fecha === hoy);
if (!actual) return [];
const dia = s => Date.parse(`${s}T00:00:00Z`) / 86400000;
const consumos = [];
for (let i = 1; i < historial.length; i++) {
  const anterior = historial[i - 1];
  const siguiente = historial[i];
  if (dia(siguiente.fecha) - dia(anterior.fecha) !== 1) continue;
  if (dia(hoy) - dia(siguiente.fecha) > 6) continue;
  const consumoAparente = anterior.stock + siguiente.comprado - siguiente.stock;
  if (Number.isFinite(consumoAparente) && consumoAparente >= 0) consumos.push(consumoAparente);
}
const recientes = consumos.slice(-7);
const suficiente = recientes.length >= 3;
const promedio = suficiente ? recientes.reduce((a, b) => a + b, 0) / recientes.length : null;
const margen = 0.10;
const sugerencia = suficiente ? Math.max(0, Math.ceil(((promedio * (1 + margen)) - actual.stock) * 2) / 2) : null;
const kg = n => n.toFixed(2).replace('.', ',');
let mensaje;
if (suficiente) {
  mensaje = [
    'SIG La Maestra - Reposicion de pan',
    `Datos ingresados en MySQL el ${hoy}.`,
    `Pan comprado hoy: ${kg(actual.comprado)} kg.`,
    `Stock informado hoy: ${kg(actual.stock)} kg.`,
    `Consumo aparente promedio: ${kg(promedio)} kg/dia.`,
    `Intervalos diarios validos: ${recientes.length}.`,
    'Margen de seguridad: 10%.',
    `Compra sugerida para la proxima jornada: ${kg(sugerencia)} kg.`,
    '',
    'El consumo aparente puede incluir merma y no equivale a ventas exactas.',
    'El encargado debe revisar la cifra y aprobar, ajustar o rechazar la compra.',
    'Este flujo NO realiza pedidos automaticos.'
  ].join('\n');
} else {
  mensaje = [
    'SIG La Maestra - Reposicion de pan',
    `Datos de pan registrados en MySQL el ${hoy}.`,
    `Pan comprado: ${kg(actual.comprado)} kg.`,
    `Stock informado: ${kg(actual.stock)} kg.`,
    '',
    'No hay historial diario consecutivo suficiente para calcular una sugerencia.',
    `Intervalos validos disponibles: ${recientes.length}; minimo requerido: 3.`,
    'El encargado debe determinar manualmente la compra y seguir registrando datos.',
    'Este flujo NO realiza pedidos automaticos.'
  ].join('\n');
}
return [{ json: { fecha: hoy, sugerencia_kg: sugerencia, mensaje } }];

const resultado = $('Calcular sugerencia para Telegram').first().json;
const estado = $getWorkflowStaticData('global');
estado.ultimaFechaAvisada = resultado.fecha;
return [{ json: { fecha: resultado.fecha, mensaje_enviado: true } }];
